/*
 * JCS Business Suite Web
 * BusinessLogoDomain.ts
 *
 * Domain validation and image-processing rules for:
 *
 * - Logos uploaded by the Business Owner.
 * - Premium logos generated by Sofía.
 * - Base64 image responses from the Cloud Function.
 * - Browser image normalization.
 * - Transparent 1024 × 1024 PNG output.
 * - Safe branding metadata.
 *
 * Firebase, Firestore and React code must not live here.
 */

import {
  BUSINESS_LOGO_MAX_BASE64_LENGTH,
  BUSINESS_LOGO_MAX_FILE_SIZE_BYTES,
  BUSINESS_LOGO_MAX_SOURCE_DIMENSION,
  BUSINESS_LOGO_OUTPUT_MIME_TYPE,
  BUSINESS_LOGO_SUPPORTED_MIME_TYPES,
  BUSINESS_LOGO_TARGET_HEIGHT,
  BUSINESS_LOGO_TARGET_WIDTH,
  DEFAULT_BUSINESS_LOGO_ACCENT_COLOR,
  DEFAULT_BUSINESS_LOGO_MIME_TYPE,
  DEFAULT_BUSINESS_NAME,
  isBusinessLogoFileSizeAllowed,
  isSupportedBusinessLogoMimeType,
  normalizeBusinessLogoConfidence,
  sanitizeStorageSegment,
} from "./BusinessLogoConstants";

import {
  clampLogoConfidence,
  createBusinessLogoID,
} from "./BusinessLogoTypes";

import type {
  BusinessBrandingSettings,
  BusinessLogoGenerationResponse,
  BusinessLogoOption,
  BusinessLogoRecord,
  BusinessLogoRenderingMode,
  BusinessLogoSource,
  UploadedBusinessLogoInput,
} from "./BusinessLogoTypes";

// MARK: - Validation Result

export type BusinessLogoValidationResult =
  | {
      isValid: true;
    }
  | {
      isValid: false;
      errorMessage: string;
    };

// MARK: - Image Metadata

export interface BusinessLogoImageMetadata {
  width: number;
  height: number;
  sizeBytes: number;
  mimeType: string;
}

// MARK: - Normalized Image

export interface NormalizedBusinessLogoImage {
  blob: Blob;
  file: File;
  width: number;
  height: number;
  sizeBytes: number;
  mimeType: typeof BUSINESS_LOGO_OUTPUT_MIME_TYPE;
  originalFileName: string;
  storedFileName: string;
  previewURL: string;
}

// MARK: - Decoded Generated Logo

export interface DecodedGeneratedBusinessLogo {
  blob: Blob;
  file: File;
  imageDataURL: string;
  mimeType: string;
  sizeBytes: number;
  width: number;
  height: number;
}

// MARK: - Source Validation

export function validateUploadedBusinessLogoInput(
  input: UploadedBusinessLogoInput,
): BusinessLogoValidationResult {
  if (!input.businessID.trim()) {
    return {
      isValid: false,
      errorMessage:
        "The business ID is required before uploading a logo.",
    };
  }

  if (!input.ownerUID.trim()) {
    return {
      isValid: false,
      errorMessage:
        "The Business Owner identity is required before uploading a logo.",
    };
  }

  if (!(input.file instanceof File)) {
    return {
      isValid: false,
      errorMessage:
        "Choose a valid image file.",
    };
  }

  return validateBusinessLogoFile(input.file);
}

export function validateBusinessLogoFile(
  file: File,
): BusinessLogoValidationResult {
  if (!(file instanceof File)) {
    return {
      isValid: false,
      errorMessage:
        "Choose a valid image file.",
    };
  }

  if (!isSupportedBusinessLogoMimeType(file.type)) {
    return {
      isValid: false,
      errorMessage:
        "Choose a PNG, JPEG or WebP image.",
    };
  }

  if (!isBusinessLogoFileSizeAllowed(file.size)) {
    return {
      isValid: false,
      errorMessage:
        `The selected logo must be smaller than ${formatFileSize(
          BUSINESS_LOGO_MAX_FILE_SIZE_BYTES,
        )}.`,
    };
  }

  return {
    isValid: true,
  };
}

// MARK: - File Metadata

export async function readBusinessLogoImageMetadata(
  file: File,
): Promise<BusinessLogoImageMetadata> {
  const validation = validateBusinessLogoFile(file);

  if (!validation.isValid) {
    throw new Error(validation.errorMessage);
  }

  const objectURL = URL.createObjectURL(file);

  try {
    const image = await loadHTMLImage(objectURL);

    const width = image.naturalWidth;
    const height = image.naturalHeight;

    validateImageDimensions(width, height);

    return {
      width,
      height,
      sizeBytes: file.size,
      mimeType:
        file.type.trim().toLowerCase() ||
        DEFAULT_BUSINESS_LOGO_MIME_TYPE,
    };
  } finally {
    URL.revokeObjectURL(objectURL);
  }
}

// MARK: - Browser Normalization

/**
 * Converts an uploaded image to a transparent 1024 × 1024 PNG.
 *
 * The source keeps its aspect ratio and is centered inside the square
 * canvas without cropping. Empty space remains transparent.
 */
export async function normalizeUploadedBusinessLogo(
  file: File,
): Promise<NormalizedBusinessLogoImage> {
  const validation = validateBusinessLogoFile(file);

  if (!validation.isValid) {
    throw new Error(validation.errorMessage);
  }

  const sourceURL = URL.createObjectURL(file);

  try {
    const sourceImage = await loadHTMLImage(sourceURL);

    validateImageDimensions(
      sourceImage.naturalWidth,
      sourceImage.naturalHeight,
    );

    const canvas = createTransparentLogoCanvas();

    const context = canvas.getContext("2d", {
      alpha: true,
    });

    if (!context) {
      throw new Error(
        "The browser could not prepare the business logo.",
      );
    }

    context.clearRect(
      0,
      0,
      BUSINESS_LOGO_TARGET_WIDTH,
      BUSINESS_LOGO_TARGET_HEIGHT,
    );

    context.imageSmoothingEnabled = true;
    context.imageSmoothingQuality = "high";

    const destinationRect = calculateAspectFitRect({
      sourceWidth: sourceImage.naturalWidth,
      sourceHeight: sourceImage.naturalHeight,
      targetWidth: BUSINESS_LOGO_TARGET_WIDTH,
      targetHeight: BUSINESS_LOGO_TARGET_HEIGHT,
    });

    context.drawImage(
      sourceImage,
      destinationRect.x,
      destinationRect.y,
      destinationRect.width,
      destinationRect.height,
    );

    const blob = await canvasToPNGBlob(canvas);

    const storedFileName = createStoredBusinessLogoFileName({
      prefix: "uploaded-logo",
      originalFileName: file.name,
    });

    const normalizedFile = new File(
      [blob],
      storedFileName,
      {
        type: BUSINESS_LOGO_OUTPUT_MIME_TYPE,
        lastModified: Date.now(),
      },
    );

    return {
      blob,
      file: normalizedFile,
      width: BUSINESS_LOGO_TARGET_WIDTH,
      height: BUSINESS_LOGO_TARGET_HEIGHT,
      sizeBytes: normalizedFile.size,
      mimeType: BUSINESS_LOGO_OUTPUT_MIME_TYPE,
      originalFileName: file.name,
      storedFileName,
      previewURL: URL.createObjectURL(blob),
    };
  } finally {
    URL.revokeObjectURL(sourceURL);
  }
}

// MARK: - Generated Logo Response

export function validateBusinessLogoGenerationResponse(
  response: BusinessLogoGenerationResponse,
): BusinessLogoValidationResult {
  if (!response.success) {
    return {
      isValid: false,
      errorMessage:
        response.error?.trim() ||
        response.message?.trim() ||
        "Sofía could not generate the business logo.",
    };
  }

  const imageBase64 = response.imageBase64?.trim() ?? "";

  if (!imageBase64) {
    return {
      isValid: false,
      errorMessage:
        "Sofía did not return image data.",
    };
  }

  if (imageBase64.length > BUSINESS_LOGO_MAX_BASE64_LENGTH) {
    return {
      isValid: false,
      errorMessage:
        "The generated logo image is larger than the supported limit.",
    };
  }

  const mimeType = normalizeMimeType(
    response.mimeType ||
    extractMimeTypeFromDataURL(imageBase64) ||
    DEFAULT_BUSINESS_LOGO_MIME_TYPE,
  );

  if (!isSupportedBusinessLogoMimeType(mimeType)) {
    return {
      isValid: false,
      errorMessage:
        "Sofía returned an unsupported image format.",
    };
  }

  return {
    isValid: true,
  };
}

export async function decodeGeneratedBusinessLogo(
  response: BusinessLogoGenerationResponse,
  businessName: string,
): Promise<DecodedGeneratedBusinessLogo> {
  const validation =
    validateBusinessLogoGenerationResponse(response);

  if (!validation.isValid) {
    throw new Error(validation.errorMessage);
  }

  const rawBase64 = response.imageBase64?.trim() ?? "";

  const mimeType = normalizeMimeType(
    response.mimeType ||
    extractMimeTypeFromDataURL(rawBase64) ||
    DEFAULT_BUSINESS_LOGO_MIME_TYPE,
  );

  const binaryData = decodeBase64ToUint8Array(
    stripBase64DataURLPrefix(rawBase64),
  );

  /*
 * Copy the decoded bytes into a standard ArrayBuffer.
 *
 * TypeScript distinguishes ArrayBuffer from ArrayBufferLike,
 * while BlobPart requires a regular ArrayBuffer-compatible view.
 */
const sourceArrayBuffer =
  new ArrayBuffer(
    binaryData.byteLength,
  );

new Uint8Array(
  sourceArrayBuffer,
).set(
  binaryData,
);

const sourceBlob =
  new Blob(
    [
      sourceArrayBuffer,
    ],
    {
      type:
        mimeType,
    },
  );

  if (sourceBlob.size <= 0) {
    throw new Error(
      "Sofía returned empty image data.",
    );
  }

  const sourceFile = new File(
    [sourceBlob],
    createStoredBusinessLogoFileName({
      prefix: "sofia-source-logo",
      originalFileName:
        response.fileName ||
        businessName ||
        DEFAULT_BUSINESS_NAME,
    }),
    {
      type: mimeType,
      lastModified: Date.now(),
    },
  );

  const normalized = await normalizeGeneratedBusinessLogo(
    sourceFile,
    businessName,
  );

  return {
    blob: normalized.blob,
    file: normalized.file,
    imageDataURL: await blobToDataURL(
      normalized.blob,
    ),
    mimeType: normalized.mimeType,
    sizeBytes: normalized.sizeBytes,
    width: normalized.width,
    height: normalized.height,
  };
}

export async function normalizeGeneratedBusinessLogo(
  file: File,
  businessName: string,
): Promise<NormalizedBusinessLogoImage> {
  const normalized =
    await normalizeUploadedBusinessLogo(file);

  const storedFileName =
    createStoredBusinessLogoFileName({
      prefix: "sofia-logo",
      originalFileName:
        businessName ||
        file.name ||
        DEFAULT_BUSINESS_NAME,
    });

  const generatedFile = new File(
    [normalized.blob],
    storedFileName,
    {
      type: BUSINESS_LOGO_OUTPUT_MIME_TYPE,
      lastModified: Date.now(),
    },
  );

  URL.revokeObjectURL(normalized.previewURL);

  return {
    ...normalized,
    file: generatedFile,
    sizeBytes: generatedFile.size,
    originalFileName: file.name,
    storedFileName,
    previewURL: URL.createObjectURL(
      generatedFile,
    ),
  };
}

// MARK: - Sofia Option Creation

export function createBusinessLogoOption(
  input: {
    businessID: string;
    businessName: string;
    title: string;
    subtitle: string;
    confidence: number;
    isSofiaRecommended: boolean;
    creativeBrief: string;
    promptUsed: string;
    mimeType: string;
    imageBase64: string;
  },
): BusinessLogoOption {
  const nowISO = new Date().toISOString();

  return {
    id: createBusinessLogoID(),

    businessID: input.businessID.trim(),
    businessName:
      normalizeBusinessName(
        input.businessName,
      ),

    title:
      input.title.trim() ||
      "Sofía Premium Logo",

    subtitle:
      input.subtitle.trim() ||
      "Premium AI-generated brand identity",

    source: "ai-generated",
    status: "temporary",

    confidence: clampLogoConfidence(
      input.confidence,
    ),

    isSofiaRecommended:
      input.isSofiaRecommended,

    creativeBrief:
      input.creativeBrief.trim(),

    promptUsed:
      input.promptUsed.trim(),

    mimeType:
      normalizeMimeType(
        input.mimeType,
      ),

    imageBase64:
      input.imageBase64.trim(),

    createdAtISO: nowISO,
  };
}

// MARK: - Persisted Logo Record

export function createBusinessLogoRecord(
  input: {
    id?: string;

    businessID: string;
    ownerUID: string;
    createdByUID: string;

    businessName: string;

    source: BusinessLogoSource;

    storagePath: string;
    downloadURL: string;

    originalFileName: string;
    storedFileName: string;
    mimeType: string;

    width?: number | null;
    height?: number | null;
    sizeBytes?: number | null;

    supportsAccentColor?: boolean;
    renderingMode?: BusinessLogoRenderingMode;
    useAccentColor?: boolean;

    creativeBrief?: string;
    promptUsed?: string;
  },
): BusinessLogoRecord {
  const nowISO = new Date().toISOString();

  const supportsAccentColor =
    input.supportsAccentColor === true;

  const renderingMode =
    supportsAccentColor &&
    input.renderingMode === "template"
      ? "template"
      : "original";

  const useAccentColor =
    renderingMode === "template" &&
    input.useAccentColor === true;

  return {
    id:
      input.id?.trim() ||
      createBusinessLogoID(),

    businessID:
      input.businessID.trim(),

    ownerUID:
      input.ownerUID.trim(),

    createdByUID:
      input.createdByUID.trim(),

    businessName:
      normalizeBusinessName(
        input.businessName,
      ),

    source:
      input.source,

    status:
      "active",

    storagePath:
      input.storagePath.trim(),

    downloadURL:
      input.downloadURL.trim(),

    originalFileName:
      input.originalFileName.trim(),

    storedFileName:
      input.storedFileName.trim(),

    mimeType:
      normalizeMimeType(
        input.mimeType,
      ),

    width:
      normalizeNullableDimension(
        input.width,
      ),

    height:
      normalizeNullableDimension(
        input.height,
      ),

    sizeBytes:
      normalizeNullableFileSize(
        input.sizeBytes,
      ),

    supportsAccentColor,

    renderingMode,

    useAccentColor,

    creativeBrief:
      input.creativeBrief?.trim() ?? "",

    promptUsed:
      input.promptUsed?.trim() ?? "",

    createdAtISO:
      nowISO,

    updatedAtISO:
      nowISO,
  };
}

// MARK: - Branding Settings

export function createBusinessBrandingSettings(
  input: {
    businessID: string;
    companyName: string;
    accentColorName?: string;

    activeLogoID?: string;
    activeLogoSource?: BusinessLogoSource;

    logoStoragePath?: string;
    logoDownloadURL?: string;

    logoRenderingMode?: BusinessLogoRenderingMode;
    logoSupportsAccentColor?: boolean;
    useAccentColorForLogo?: boolean;
  },
): BusinessBrandingSettings {
  const logoSupportsAccentColor =
    input.logoSupportsAccentColor === true;

  const logoRenderingMode =
    logoSupportsAccentColor &&
    input.logoRenderingMode === "template"
      ? "template"
      : "original";

  const useAccentColorForLogo =
    logoRenderingMode === "template" &&
    input.useAccentColorForLogo === true;

  return {
    businessID:
      input.businessID.trim(),

    companyName:
      normalizeBusinessName(
        input.companyName,
      ),

    accentColorName:
      normalizeAccentColorName(
        input.accentColorName,
      ),

    activeLogoID:
      input.activeLogoID?.trim() ?? "",

    activeLogoSource:
      input.activeLogoSource ?? "default",

    logoStoragePath:
      input.logoStoragePath?.trim() ?? "",

    logoDownloadURL:
      input.logoDownloadURL?.trim() ?? "",

    logoRenderingMode,

    logoSupportsAccentColor,

    useAccentColorForLogo,

    updatedAtISO:
      new Date().toISOString(),
  };
}

// MARK: - Safe Normalization

export function normalizeBusinessName(
  value: string,
): string {
  const normalizedValue = value
    .trim()
    .replace(/\s+/g, " ")
    .slice(0, 160);

  return normalizedValue ||
    DEFAULT_BUSINESS_NAME;
}

export function normalizeAccentColorName(
  value?: string,
): string {
  const normalizedValue = value
    ?.trim()
    .replace(/\s+/g, "")
    .slice(0, 64);

  return normalizedValue ||
    DEFAULT_BUSINESS_LOGO_ACCENT_COLOR;
}

export function normalizeMimeType(
  value: string,
): string {
  const normalizedValue = value
    .trim()
    .toLowerCase()
    .split(";")[0];

  return normalizedValue ||
    DEFAULT_BUSINESS_LOGO_MIME_TYPE;
}

export function normalizeBusinessLogoSource(
  value: unknown,
): BusinessLogoSource {
  switch (value) {
    case "ai-generated":
    case "uploaded":
    case "default":
      return value;

    default:
      return "default";
  }
}

export function normalizeBusinessLogoRenderingMode(
  value: unknown,
): BusinessLogoRenderingMode {
  return value === "template"
    ? "template"
    : "original";
}

// MARK: - File Naming

export function createStoredBusinessLogoFileName(
  input: {
    prefix: string;
    originalFileName: string;
  },
): string {
  const safePrefix = sanitizeStorageSegment(
    input.prefix,
    "business-logo",
  );

  const originalBaseName = removeFileExtension(
    input.originalFileName,
  );

  const safeOriginalName = sanitizeStorageSegment(
    originalBaseName,
    "logo",
  );

  const logoID = sanitizeStorageSegment(
    createBusinessLogoID(),
    Date.now().toString(36),
  );

  return [
    safePrefix,
    safeOriginalName,
    logoID,
  ].join("-") + ".png";
}

// MARK: - Base64

export function stripBase64DataURLPrefix(
  value: string,
): string {
  const trimmedValue = value.trim();

  const commaIndex =
    trimmedValue.indexOf(",");

  if (
    trimmedValue.startsWith("data:") &&
    commaIndex >= 0
  ) {
    return trimmedValue
      .slice(commaIndex + 1)
      .replace(/\s+/g, "");
  }

  return trimmedValue.replace(/\s+/g, "");
}

export function extractMimeTypeFromDataURL(
  value: string,
): string | null {
  const match = value
    .trim()
    .match(/^data:([^;,]+)[;,]/i);

  return match?.[1]
    ? normalizeMimeType(match[1])
    : null;
}

export function decodeBase64ToUint8Array(
  value: string,
): Uint8Array {
  const normalizedValue =
    stripBase64DataURLPrefix(value);

  if (!normalizedValue) {
    throw new Error(
      "The generated image data is empty.",
    );
  }

  let binaryString: string;

  try {
    binaryString = globalThis.atob(
      normalizedValue,
    );
  } catch {
    throw new Error(
      "The generated image data is not valid Base64.",
    );
  }

  const bytes = new Uint8Array(
    binaryString.length,
  );

  for (
    let index = 0;
    index < binaryString.length;
    index += 1
  ) {
    bytes[index] =
      binaryString.charCodeAt(index);
  }

  return bytes;
}

export async function blobToDataURL(
  blob: Blob,
): Promise<string> {
  return new Promise(
    (resolve, reject) => {
      const reader = new FileReader();

      reader.onload = () => {
        if (
          typeof reader.result === "string"
        ) {
          resolve(reader.result);
          return;
        }

        reject(
          new Error(
            "The image preview could not be created.",
          ),
        );
      };

      reader.onerror = () => {
        reject(
          new Error(
            "The image preview could not be read.",
          ),
        );
      };

      reader.readAsDataURL(blob);
    },
  );
}

// MARK: - Preview Cleanup

export function revokeBusinessLogoPreviewURL(
  previewURL: string,
): void {
  const normalizedURL =
    previewURL.trim();

  if (
    normalizedURL.startsWith("blob:")
  ) {
    URL.revokeObjectURL(
      normalizedURL,
    );
  }
}

// MARK: - Private Browser Helpers

function createTransparentLogoCanvas(): HTMLCanvasElement {
  const canvas =
    document.createElement("canvas");

  canvas.width =
    BUSINESS_LOGO_TARGET_WIDTH;

  canvas.height =
    BUSINESS_LOGO_TARGET_HEIGHT;

  return canvas;
}

function loadHTMLImage(
  sourceURL: string,
): Promise<HTMLImageElement> {
  return new Promise(
    (resolve, reject) => {
      const image = new Image();

      image.decoding = "async";

      image.onload = () => {
        resolve(image);
      };

      image.onerror = () => {
        reject(
          new Error(
            "The selected file could not be opened as an image.",
          ),
        );
      };

      image.src = sourceURL;
    },
  );
}

function canvasToPNGBlob(
  canvas: HTMLCanvasElement,
): Promise<Blob> {
  return new Promise(
    (resolve, reject) => {
      canvas.toBlob(
        (blob) => {
          if (!blob) {
            reject(
              new Error(
                "The business logo could not be converted to PNG.",
              ),
            );
            return;
          }

          resolve(blob);
        },
        BUSINESS_LOGO_OUTPUT_MIME_TYPE,
        1,
      );
    },
  );
}

function calculateAspectFitRect(
  input: {
    sourceWidth: number;
    sourceHeight: number;
    targetWidth: number;
    targetHeight: number;
  },
): {
  x: number;
  y: number;
  width: number;
  height: number;
} {
  const scale = Math.min(
    input.targetWidth /
      input.sourceWidth,
    input.targetHeight /
      input.sourceHeight,
    1,
  );

  const width =
    Math.max(
      1,
      Math.round(
        input.sourceWidth * scale,
      ),
    );

  const height =
    Math.max(
      1,
      Math.round(
        input.sourceHeight * scale,
      ),
    );

  return {
    x: Math.round(
      (input.targetWidth - width) / 2,
    ),

    y: Math.round(
      (input.targetHeight - height) / 2,
    ),

    width,
    height,
  };
}

function validateImageDimensions(
  width: number,
  height: number,
): void {
  if (
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width <= 0 ||
    height <= 0
  ) {
    throw new Error(
      "The selected logo has invalid dimensions.",
    );
  }

  if (
    width >
      BUSINESS_LOGO_MAX_SOURCE_DIMENSION ||
    height >
      BUSINESS_LOGO_MAX_SOURCE_DIMENSION
  ) {
    throw new Error(
      `The selected logo cannot be larger than ${BUSINESS_LOGO_MAX_SOURCE_DIMENSION} pixels on either side.`,
    );
  }
}

// MARK: - Private Normalization

function normalizeNullableDimension(
  value: number | null | undefined,
): number | null {
  if (
    typeof value !== "number" ||
    !Number.isFinite(value) ||
    value <= 0
  ) {
    return null;
  }

  return Math.round(value);
}

function normalizeNullableFileSize(
  value: number | null | undefined,
): number | null {
  if (
    typeof value !== "number" ||
    !Number.isFinite(value) ||
    value <= 0
  ) {
    return null;
  }

  return Math.round(value);
}

function removeFileExtension(
  fileName: string,
): string {
  const normalizedFileName =
    fileName.trim();

  const finalPathComponent =
    normalizedFileName
      .split(/[\\/]/)
      .pop() ?? "";

  return finalPathComponent.replace(
    /\.[^.]+$/,
    "",
  );
}

function formatFileSize(
  sizeBytes: number,
): string {
  if (
    !Number.isFinite(sizeBytes) ||
    sizeBytes <= 0
  ) {
    return "0 bytes";
  }

  const megabytes =
    sizeBytes / (1024 * 1024);

  if (megabytes >= 1) {
    return `${Number(
      megabytes.toFixed(1),
    )} MB`;
  }

  const kilobytes =
    sizeBytes / 1024;

  return `${Math.round(
    kilobytes,
  )} KB`;
}